// ---- math/Quadtree.js --------------------------------------------------
// =============================================================================
// Quadtree — 2D (XZ-plane) broadphase spatial index.
//
// Gameplay is effectively 2.5D: units, smoke and projectile sweeps are queried
// against footprints on the ground plane, so a quadtree over XZ gives the
// spatial partitioning the spec calls for without paying for a full octree.
// (Heights are bounded and cheap to test in the narrow phase.)
//
// Items are `{ x, z, r, ref }` — a bounding circle plus an opaque payload. The
// tree is cheap to rebuild, so `World` clears and refills it once per frame
// rather than tracking incremental moves.
// =============================================================================

class Quadtree {
  /**
   * @param {{x:number, z:number, hw:number, hh:number}} boundary center + half-extents
   * @param {number} capacity items per node before it subdivides
   * @param {number} maxDepth hard recursion cap
   */
  constructor(boundary, capacity = 8, maxDepth = 8, _depth = 0) {
    this.boundary = boundary;
    this.capacity = capacity;
    this.maxDepth = maxDepth;
    this._depth = _depth;
    this.items = [];
    this.divided = false;
    this.children = null;
  }

  clear() {
    this.items.length = 0;
    this.divided = false;
    this.children = null;
  }

  _subdivide() {
    const { x, z, hw, hh } = this.boundary;
    const qw = hw / 2, qh = hh / 2;
    const d = this._depth + 1;
    this.children = [
      new Quadtree({ x: x - qw, z: z - qh, hw: qw, hh: qh }, this.capacity, this.maxDepth, d),
      new Quadtree({ x: x + qw, z: z - qh, hw: qw, hh: qh }, this.capacity, this.maxDepth, d),
      new Quadtree({ x: x - qw, z: z + qh, hw: qw, hh: qh }, this.capacity, this.maxDepth, d),
      new Quadtree({ x: x + qw, z: z + qh, hw: qw, hh: qh }, this.capacity, this.maxDepth, d),
    ];
    this.divided = true;
  }

  _contains(item) {
    const b = this.boundary;
    return (
      item.x >= b.x - b.hw && item.x < b.x + b.hw &&
      item.z >= b.z - b.hh && item.z < b.z + b.hh
    );
  }

  /**
   * Insert by item *center*. Items are point-indexed (their radius is only
   * consulted at query time), which keeps insertion O(depth) and avoids an
   * item living in several nodes at once.
   */
  insert(item) {
    if (!this._contains(item)) return false;

    if (!this.divided) {
      if (this.items.length < this.capacity || this._depth >= this.maxDepth) {
        this.items.push(item);
        return true;
      }
      this._subdivide();
      // push existing points down into the new children
      for (const it of this.items) {
        for (const c of this.children) if (c.insert(it)) break;
      }
      this.items.length = 0;
    }
    for (const c of this.children) if (c.insert(item)) return true;
    return false;
  }

  // --- queries ------------------------------------------------------------

  /** True if this node's box overlaps an axis-aligned range (center+half). */
  _intersectsAABB(cx, cz, hw, hh) {
    const b = this.boundary;
    return !(
      cx - hw > b.x + b.hw || cx + hw < b.x - b.hw ||
      cz - hh > b.z + b.hh || cz + hh < b.z - b.hh
    );
  }

  /**
   * All items whose bounding circle intersects an AABB (center + half-extents).
   * @param {Array} out results are pushed here (reused to avoid allocation)
   */
  queryAABB(cx, cz, hw, hh, out = []) {
    if (!this._intersectsAABB(cx, cz, hw, hh)) return out;
    if (this.divided) {
      for (const c of this.children) c.queryAABB(cx, cz, hw, hh, out);
    } else {
      for (const it of this.items) {
        if (
          it.x + it.r >= cx - hw && it.x - it.r <= cx + hw &&
          it.z + it.r >= cz - hh && it.z - it.r <= cz + hh
        ) out.push(it);
      }
    }
    return out;
  }

  /** All items whose circle intersects the query circle (cx,cz,cr). */
  queryCircle(cx, cz, cr, out = []) {
    // Broadphase against the circle's AABB, then a precise circle test.
    const candidates = this.queryAABB(cx, cz, cr, cr, []);
    for (const it of candidates) {
      const dx = it.x - cx, dz = it.z - cz;
      const rr = cr + it.r;
      if (dx * dx + dz * dz <= rr * rr) out.push(it);
    }
    return out;
  }

  /**
   * Broadphase for a swept segment (x0,z0)->(x1,z1), inflated by `pad`.
   * Returns items whose AABB overlaps the segment's padded bounding box; the
   * caller runs the precise segment/sphere test. Good enough for projectile
   * sweeps and LoS rays where segments are short relative to the map.
   */
  querySegment(x0, z0, x1, z1, pad, out = []) {
    const minX = Math.min(x0, x1) - pad, maxX = Math.max(x0, x1) + pad;
    const minZ = Math.min(z0, z1) - pad, maxZ = Math.max(z0, z1) + pad;
    const cx = (minX + maxX) / 2, cz = (minZ + maxZ) / 2;
    const hw = (maxX - minX) / 2, hh = (maxZ - minZ) / 2;
    return this.queryAABB(cx, cz, hw, hh, out);
  }
}


